#include "metaCommandObject.h"
#include "backend/backend_picture.h"   // ibBackendPicture::GetIconFromBase64

/* PNG */
static const wxString s_command_64_png = wxT("");

wxIcon ibValueMetaObjectCommand::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectCommand::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_command_64_png, wxSize(16, 16));

	return icon;
}
